// Check each item for approaching filing deadlines
const response = $input.first().json;
const items = response?.data?.boards?.[0]?.items_page?.items || [];
const today = new Date();
today.setHours(0, 0, 0, 0);

const thresholds = [30, 14, 7];
const alerts = [];

for (const item of items) {
  const columns = {};
  for (const col of item.column_values || []) {
    columns[col.id] = { text: col.text, value: col.value ? JSON.parse(col.value) : null };
  }

  const statusText = columns.color_mm0fj7fm?.text || '';
  const filingDeadlineStr = columns.date_mm0fgzne?.text || '';
  const patientName = item.name;
  const denialCode = columns.dropdown_mm0ffjcd?.text || '';
  const planType = columns.dropdown_mm0fjy49?.text || '';
  const deniedAmount = columns.numeric_mm0fh3jn?.text || '0';

  // Skip resolved items (Won, Lost)
  if (['Won', 'Lost'].includes(statusText)) continue;

  if (!filingDeadlineStr) continue;

  const deadline = new Date(filingDeadlineStr);
  deadline.setHours(0, 0, 0, 0);
  const daysRemaining = Math.ceil((deadline - today) / (1000 * 60 * 60 * 24));

  // Check if any threshold is hit
  for (const threshold of thresholds) {
    if (daysRemaining === threshold || (daysRemaining <= threshold && daysRemaining > 0)) {
      // Only alert at exact thresholds or if deadline is critically close
      if (daysRemaining === threshold || daysRemaining <= 7) {
        const urgency = daysRemaining <= 7 ? 'CRITICAL' : daysRemaining <= 14 ? 'WARNING' : 'NOTICE';
        alerts.push({
          item_id: item.id,
          patient_name: patientName,
          denial_code: denialCode,
          plan_type: planType,
          denied_amount: deniedAmount,
          appeal_status: statusText,
          filing_deadline: filingDeadlineStr,
          days_remaining: daysRemaining,
          urgency,
          group: item.group?.title || ''
        });
        break;  // One alert per item
      }
    }
  }
}

// Sort by urgency (most urgent first)
alerts.sort((a, b) => a.days_remaining - b.days_remaining);

return alerts.length > 0
  ? alerts.map(a => ({ json: a }))
  : [{ json: { no_alerts: true, items_checked: items.length } }];

// Build deadline alert message for RingCentral
const items = $input.all().map(i => i.json);

let message = 'FILING DEADLINE ALERTS\n' + '='.repeat(40) + '\n\n';

for (const item of items) {
  const emoji = item.urgency === 'CRITICAL' ? '[CRITICAL]' :
                item.urgency === 'WARNING' ? '[WARNING]' : '[NOTICE]';

  message += `${emoji} ${item.patient_name}\n`;
  message += `  Code: ${item.denial_code}\n`;
  message += `  Amount: $${item.denied_amount}\n`;
  message += `  Status: ${item.appeal_status}\n`;
  message += `  Deadline: ${item.filing_deadline} (${item.days_remaining} days)\n`;
  if (item.days_remaining <= 7) {
    message += `  ACTION REQUIRED: File immediately or escalate!\n`;
  }
  message += '\n';
}

message += `Board: https://phw-team.monday.com/boards/18399605169\n`;
message += `Total alerts: ${items.length}`;

return [{
  json: {
    alert_message: message,
    alert_count: items.length,
    critical_count: items.filter(i => i.urgency === 'CRITICAL').length
  }
}];

// Parse Monday.com status change webhook for escalation
const input = $input.first().json;
const event = input.event || input;

const itemId = String(event.pulseId || event.itemId || input.itemId || '');
const statusLabel = event.value?.label?.text || event.value?.name || input.status || '';

return [{
  json: {
    item_id: itemId,
    new_status: statusLabel,
    is_escalation: statusLabel === 'Escalated',
    is_won: statusLabel === 'Won',
    is_lost: statusLabel === 'Lost'
  }
}];

// Build escalation routing message based on plan type
const response = $input.first().json;
const item = response?.data?.items?.[0];

if (!item) {
  throw new Error('Item not found for escalation');
}

const columns = {};
for (const col of item.column_values || []) {
  columns[col.id] = { text: col.text, value: col.value ? JSON.parse(col.value) : null };
}

const patientName = item.name;
const planType = columns.dropdown_mm0fjy49?.text || 'Unknown';
const denialCode = columns.dropdown_mm0ffjcd?.text || '';
const deniedAmount = columns.numeric_mm0fh3jn?.text || '0';
const filingDeadline = columns.date_mm0fgzne?.text || '';
const denialDate = columns.date_mm0frn70?.text || '';

// Calculate days remaining for external appeal
const today = new Date();
const deadline120 = new Date(denialDate);
deadline120.setDate(deadline120.getDate() + 120);  // External appeal deadline
const daysToExternal = Math.ceil((deadline120 - today) / (1000 * 60 * 60 * 24));

let escalationMessage;
let escalationPath;

if (planType === 'Fully Insured') {
  escalationPath = 'NY DFS External Appeal';
  escalationMessage = `ESCALATION — FULLY INSURED PLAN\n` +
    `${'='.repeat(40)}\n\n` +
    `Patient: ${patientName}\n` +
    `Denial Code: ${denialCode}\n` +
    `Amount: $${deniedAmount}\n\n` +
    `ROUTE: NY Department of Financial Services External Appeal\n` +
    `TYPE: Independent External Review (binding, 30-day review)\n` +
    `DEADLINE: ${daysToExternal} days remaining (120 days from denial)\n` +
    `FEE: $25 (waivable for financial hardship)\n\n` +
    `FILING STEPS:\n` +
    `1. Verify 2 levels of internal appeal exhausted\n` +
    `2. Gather: final denial letter, clinical records, provider letter of necessity, AOB, patient auth\n` +
    `3. File at: https://myportal.dfs.ny.gov/web/guest-applications/external-appeals\n` +
    `4. Pay $25 filing fee (or request hardship waiver)\n\n` +
    `CITATIONS:\n` +
    `- NY Insurance Law §4914\n` +
    `- 11 NYCRR 410\n` +
    `- NY Public Health Law §4900-4910\n\n` +
    `Board: https://phw-team.monday.com/boards/18399605169`;
} else {
  escalationPath = 'Federal ERISA External Review';
  escalationMessage = `ESCALATION — SELF-FUNDED / ERISA PLAN\n` +
    `${'='.repeat(40)}\n\n` +
    `Patient: ${patientName}\n` +
    `Denial Code: ${denialCode}\n` +
    `Amount: $${deniedAmount}\n\n` +
    `ROUTE: Federal External Review (CMS/DOL)\n` +
    `TYPE: Independent Review Organization (IRO) — binding on plan\n` +
    `DEADLINE: ${daysToExternal} days remaining (120 days from final internal denial)\n\n` +
    `FILING STEPS:\n` +
    `1. Verify 2 levels of internal appeal exhausted (or plan failed to comply with claims procedure)\n` +
    `2. Request Summary Plan Description (SPD) showing external review rights\n` +
    `3. Gather: final adverse determination, clinical records, provider letter, IRO authorization forms\n` +
    `4. Submit to plan's designated accredited IRO\n\n` +
    `CITATIONS:\n` +
    `- 29 CFR §2590.715-2719\n` +
    `- ACA §2719\n` +
    `- 29 USC §1133\n` +
    `- DOL Technical Release 2010-01\n\n` +
    `NOTE: State external appeal (NY DFS) does NOT apply to self-funded ERISA plans.\n\n` +
    `Board: https://phw-team.monday.com/boards/18399605169`;
}

return [{
  json: {
    item_id: item.id,
    patient_name: patientName,
    plan_type: planType,
    escalation_path: escalationPath,
    escalation_message: escalationMessage,
    days_to_external_deadline: daysToExternal
  }
}];

// Handle Won/Lost status changes — move to Resolved group
const data = $('Parse Status Change').first().json;

if (!data.is_won && !data.is_lost) {
  return [{ json: { status: 'skipped', reason: 'Not a resolution status' } }];
}

return [{
  json: {
    item_id: data.item_id,
    new_status: data.new_status,
    move_to_group: 'group_mm0fmapq'  // Resolved
  }
}];
